  "response": "<solution>\nimport sys\n\ndef main():\n    # Read all input from standard input efficiently\n    input_data = sys.stdin.read().split()\n    if not input_data:\n        return\n\n    N = int(input_data[0])\n    M = int(input_data[1])\n\n    # Extract the B and W arrays\n    B = [int(x) for x in input_data[2:2+N]]\n    W = [int(x) for x in input_data[2+N:2+N+M]]\n\n    # Sort both arrays in descending order since we want to greedily pick the maximum values available\n    B.sort(reverse=True)\n    W.sort(reverse=True)\n\n    # Compute prefix sums for black balls\n    black_prefix = [0] * (N + 1)\n    for i in range(N):\n        black_prefix[i + 1] = black_prefix[i] + B[i]\n\n    # Compute prefix sums for white balls\n    white_prefix = [0] * (M + 1)\n    for i in range(M):\n        white_prefix[i + 1] = white_prefix[i] + W[i]\n\n    # best_black_from[k] will store the maximum possible sum of black balls we can get \n    # if we choose c >= k black balls. (c is the number of chosen black balls)\n    best_black_from = [0] * (N + 1)\n    best_black_from[N] = black_prefix[N]\n    for i in range(N - 1, -1, -1):\n        best_black_from[i] = max(black_prefix[i], best_black_from[i + 1])\n\n    # Find the optimal combination of chosen white balls and black balls\n    ans = 0\n    for whites in range(min(N, M) + 1):\n        # By taking `whites` white balls, we MUST take at least `whites` black balls.\n        # So we can safely take the maximum black prefix sum available from indices >= whites.\n        current_sum = white_prefix[whites] + best_black_from[whites]\n        if current_sum > ans:\n            ans = current_sum\n\n    print(ans)\n\nif __name__ == \"__main__\":\n    main()\n</solution>",
